DROP TABLE IF EXISTS `job_card_process_days`;
CREATE TABLE `job_card_process_days` (
  `id` int NOT NULL AUTO_INCREMENT,
  `job_card_no` varchar(50) NOT NULL,
  `process_name` varchar(100) NOT NULL,
  `days` int DEFAULT '0',
  `is_completed` tinyint DEFAULT '0',
  `lead_date` date DEFAULT NULL,
  `end_date` date DEFAULT NULL,
  `in_time` datetime DEFAULT NULL,
  `out_time` datetime DEFAULT NULL,
  `actual_days` int DEFAULT NULL,
  `is_subcontract` tinyint(1) DEFAULT '0',
  `vendor_name` varchar(255) DEFAULT NULL,
  `subcontract_lead_days` int DEFAULT '0',
  `subcontract_start_date` date DEFAULT NULL,
  `subcontract_expected_date` date DEFAULT NULL,
  PRIMARY KEY (`id`),
  KEY `job_card_no` (`job_card_no`),
  KEY `idx_jcpd_cutting_lookup` (`job_card_no`,`id`),
  KEY `idx_jcpd_cutting_fast` (`job_card_no`,`process_name`,`id`),
  KEY `idx_jcpd_process_jc_id` (`process_name`,`job_card_no`,`id`),
  CONSTRAINT `job_card_process_days_ibfk_1` FOREIGN KEY (`job_card_no`) REFERENCES `job_cards` (`job_card_no`)
) ENGINE=InnoDB AUTO_INCREMENT=27351 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci;

