-- ---------------------------------
-- Table structure for `job_card_upload_reviews`
-- ---------------------------------
DROP TABLE IF EXISTS `job_card_upload_reviews`;
CREATE TABLE `job_card_upload_reviews` (
  `id` int NOT NULL AUTO_INCREMENT,
  `review_token` varchar(64) COLLATE utf8mb4_unicode_ci NOT NULL,
  `job_card_no` varchar(50) COLLATE utf8mb4_unicode_ci NOT NULL,
  `so_no` varchar(50) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `customer_name` varchar(255) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `bom_no` varchar(20) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `parent_code` varchar(30) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `child_code` varchar(30) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `item_name` varchar(500) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `source_file` varchar(255) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `uploaded_processes` json DEFAULT NULL,
  `master_processes` json DEFAULT NULL,
  `route_signature` char(64) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `review_status` varchar(50) COLLATE utf8mb4_unicode_ci NOT NULL,
  `review_decision` varchar(50) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `review_remark` text COLLATE utf8mb4_unicode_ci,
  `is_resolved` tinyint(1) NOT NULL DEFAULT '0',
  `reviewed_by` varchar(100) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `reviewed_at` datetime DEFAULT NULL,
  `created_at` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP,
  PRIMARY KEY (`id`),
  KEY `idx_upload_review_token` (`review_token`),
  KEY `idx_upload_review_status` (`review_status`),
  KEY `idx_upload_review_child` (`child_code`),
  KEY `idx_reusable_review` (`bom_no`,`parent_code`,`child_code`,`route_signature`,`is_resolved`)
) ENGINE=InnoDB AUTO_INCREMENT=1469 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

