-- ---------------------------------
-- Table structure for `oee_entries`
-- ---------------------------------
DROP TABLE IF EXISTS `oee_entries`;
CREATE TABLE `oee_entries` (
  `id` bigint NOT NULL AUTO_INCREMENT,
  `operator_completion_id` bigint DEFAULT NULL,
  `job_card_item_id` int DEFAULT NULL,
  `process_day_id` int DEFAULT NULL,
  `machine_id` int NOT NULL,
  `operator_user_id` int DEFAULT NULL,
  `entry_date` date NOT NULL,
  `shift_name` varchar(30) COLLATE utf8mb4_unicode_ci NOT NULL,
  `job_card_no` varchar(50) COLLATE utf8mb4_unicode_ci NOT NULL,
  `item_name` varchar(500) COLLATE utf8mb4_unicode_ci NOT NULL,
  `process_name` varchar(100) COLLATE utf8mb4_unicode_ci NOT NULL,
  `operator_name` varchar(100) COLLATE utf8mb4_unicode_ci NOT NULL,
  `machine_no` varchar(60) COLLATE utf8mb4_unicode_ci NOT NULL,
  `machine_name` varchar(150) COLLATE utf8mb4_unicode_ci NOT NULL,
  `machine_category` enum('CNC','VMC') COLLATE utf8mb4_unicode_ci NOT NULL,
