-- ---------------------------------
-- Table structure for `process_master_change_log`
-- ---------------------------------
DROP TABLE IF EXISTS `process_master_change_log`;
CREATE TABLE `process_master_change_log` (
  `id` int NOT NULL AUTO_INCREMENT,
  `item_code` varchar(30) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL,
  `action_type` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL,
  `old_data` json DEFAULT NULL,
  `new_data` json DEFAULT NULL,
  `change_remark` text CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL,
  `changed_by` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `changed_at` datetime DEFAULT CURRENT_TIMESTAMP,
  PRIMARY KEY (`id`),
  KEY `idx_pmcl_item_changed` (`item_code`,`changed_at`)
) ENGINE=InnoDB AUTO_INCREMENT=18 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

-- Data for `process_master_change_log` (17 rows)

-- ---------------------------------
-- Table structure for `processes`
-- ---------------------------------
DROP TABLE IF EXISTS `processes`;
CREATE TABLE `processes` (
  `id` int NOT NULL AUTO_INCREMENT,
  `process_name` varchar(100) NOT NULL,
  `created_at` timestamp NULL DEFAULT CURRENT_TIMESTAMP,
  PRIMARY KEY (`id`),
  UNIQUE KEY `uq_process_name` (`process_name`)
) ENGINE=InnoDB AUTO_INCREMENT=66 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci;

-- Data for `processes` (65 rows)

-- ---------------------------------
-- Table structure for `quality_check_details`
-- ---------------------------------
DROP TABLE IF EXISTS `quality_check_details`;
CREATE TABLE `quality_check_details` (
  `id` int NOT NULL AUTO_INCREMENT,
  `job_card_no` varchar(50) DEFAULT NULL,
  `checked_at` datetime DEFAULT NULL,
  `quality_check_id` int NOT NULL,
  `item_name` varchar(500) DEFAULT NULL,
  `actual_qty` int DEFAULT NULL,
  `process_name` varchar(100) DEFAULT NULL,
  `quality_result` enum('OK','NOT OK') DEFAULT NULL,
  `supervisor` varchar(100) DEFAULT NULL,
  PRIMARY KEY (`id`),
  KEY `quality_check_id` (`quality_check_id`),
  CONSTRAINT `quality_check_details_ibfk_1` FOREIGN KEY (`quality_check_id`) REFERENCES `quality_checks` (`id`)
) ENGINE=InnoDB AUTO_INCREMENT=30 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci;

-- Data for `quality_check_details` (4 rows)

-- ---------------------------------
-- Table structure for `quality_checks`
-- ---------------------------------
DROP TABLE IF EXISTS `quality_checks`;
CREATE TABLE `quality_checks` (
  `id` int NOT NULL AUTO_INCREMENT,
  `job_card_no` varchar(50) NOT NULL,
  `checked_at` timestamp NULL DEFAULT CURRENT_TIMESTAMP,
  PRIMARY KEY (`id`),
  KEY `job_card_no` (`job_card_no`),
  CONSTRAINT `quality_checks_ibfk_1` FOREIGN KEY (`job_card_no`) REFERENCES `job_cards` (`job_card_no`)
) ENGINE=InnoDB AUTO_INCREMENT=31 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci;

-- Data for `quality_checks` (4 rows)

-- ---------------------------------
-- Table structure for `revoke_log`
-- ---------------------------------
DROP TABLE IF EXISTS `revoke_log`;
CREATE TABLE `revoke_log` (
  `id` int NOT NULL AUTO_INCREMENT,
  `job_card_no` varchar(50) NOT NULL,
  `item_name` varchar(255) NOT NULL,
  `from_process` varchar(100) NOT NULL COMMENT 'Process where revoke happened (e.g. R/Turning)',
  `to_process` varchar(100) NOT NULL COMMENT 'Immediate previous process for rework (e.g. Cutting)',
  `revoke_qty` int NOT NULL DEFAULT '0',
  `passed_qty` int DEFAULT NULL COMMENT 'Filled when revoke is completed',
  `rejected_qty` int DEFAULT NULL COMMENT 'If some fail even after rework',
  `remarks` text,
  `status` enum('Open','Completed') NOT NULL DEFAULT 'Open',
  `created_at` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP,
  `completed_at` datetime DEFAULT NULL,
  `completed_by` varchar(100) DEFAULT NULL,
  PRIMARY KEY (`id`),
  KEY `idx_revoke_job` (`job_card_no`),
  KEY `idx_revoke_status` (`status`),
  KEY `idx_revoke_job_status` (`job_card_no`,`status`)
) ENGINE=InnoDB AUTO_INCREMENT=11 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci;

-- ---------------------------------
-- Table structure for `revoke_process_days`
-- ---------------------------------
DROP TABLE IF EXISTS `revoke_process_days`;
CREATE TABLE `revoke_process_days` (
  `id` int NOT NULL AUTO_INCREMENT,
  `revoke_id` int NOT NULL,
  `job_card_no` varchar(50) NOT NULL,
  `item_name` varchar(255) NOT NULL,
  `process_name` varchar(100) NOT NULL,
  `process_order` int NOT NULL COMMENT '1=first rework stage, 2=second, etc.',
  `lead_days` int DEFAULT '0',
  `in_time` datetime DEFAULT NULL,
  `out_time` datetime DEFAULT NULL,
  `actual_days` int DEFAULT NULL,
  `is_completed` tinyint(1) DEFAULT '0',
  `is_final` tinyint(1) DEFAULT '0' COMMENT '1 = last stage before rejoining main flow',
  `merged_to_main` tinyint(1) DEFAULT '0' COMMENT '1 = pieces rejoined main flow',
  `created_at` datetime DEFAULT CURRENT_TIMESTAMP,
  PRIMARY KEY (`id`),
  KEY `idx_rpd_revoke` (`revoke_id`),
  KEY `idx_rpd_job` (`job_card_no`),
  KEY `idx_rpd_completed` (`is_completed`),
  CONSTRAINT `revoke_process_days_ibfk_1` FOREIGN KEY (`revoke_id`) REFERENCES `revoke_log` (`id`)
) ENGINE=InnoDB AUTO_INCREMENT=19 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci;

-- ---------------------------------
-- Table structure for `rework_log`
-- ---------------------------------
DROP TABLE IF EXISTS `rework_log`;
CREATE TABLE `rework_log` (
  `id` int NOT NULL AUTO_INCREMENT,
  `job_card_no` varchar(50) NOT NULL,
  `item_name` varchar(255) NOT NULL,
  `from_process` varchar(100) NOT NULL,
  `to_process` varchar(100) NOT NULL,
  `rework_qty` int NOT NULL DEFAULT '0',
  `rejected_qty` int NOT NULL DEFAULT '0',
  `passed_qty` int DEFAULT NULL,
  `final_rejected` int DEFAULT NULL,
  `remarks` text,
  `status` enum('Open','Completed') NOT NULL DEFAULT 'Open',
  `created_at` datetime DEFAULT CURRENT_TIMESTAMP,
  `completed_at` datetime DEFAULT NULL,
  `completed_by` varchar(100) DEFAULT NULL,
  PRIMARY KEY (`id`),
  KEY `idx_rework_job` (`job_card_no`),
  KEY `idx_rework_status` (`status`),
  KEY `idx_rework_job_status` (`job_card_no`,`status`)
) ENGINE=InnoDB AUTO_INCREMENT=14 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci;

-- ---------------------------------
-- Table structure for `rework_process_days`
-- ---------------------------------
DROP TABLE IF EXISTS `rework_process_days`;
CREATE TABLE `rework_process_days` (
  `id` int NOT NULL AUTO_INCREMENT,
  `rework_id` int NOT NULL,
  `job_card_no` varchar(50) NOT NULL,
  `item_name` varchar(255) NOT NULL,
  `process_name` varchar(100) NOT NULL,
  `process_order` int NOT NULL,
  `lead_days` int DEFAULT '0',
  `in_time` datetime DEFAULT NULL,
  `out_time` datetime DEFAULT NULL,
  `actual_days` int DEFAULT NULL,
  `is_completed` tinyint(1) DEFAULT '0',
  `is_final` tinyint(1) DEFAULT '0',
